/**
 * components/IRPanel.tsx
 * Displays the intermediate code generated by the compiler
 */
import type { IRInstruction } from '../types';

interface Props { instructions: IRInstruction[] }

const OP_COLOUR: Record<string, string> = {
  REGISTER_PATIENT:   'var(--tok-identifier)',
  SET_LOCATION:       'var(--text-secondary)',
  SET_SEVERITY:       'var(--tok-severity)',
  REGISTER_AMBULANCE: 'var(--accent)',
  REGISTER_HOSPITAL:  'var(--success)',
  DISPATCH:           'var(--danger)',
  ASSIGN_ROUTE:       'var(--info)',
  SET_PRIORITY:       'var(--tok-severity)',
  STATUS:             'var(--text-muted)',
  ARRIVE:             'var(--success)',
  TRANSFER:           'var(--warning)',
  CANCEL:             'var(--danger)',
  REPORT:             'var(--info)',
};

export function IRPanel({ instructions }: Props) {
  if (!instructions.length) {
    return (
      <div className="empty-state">
        <div className="empty-state-icon">⚙️</div>
        <div className="empty-state-title">No IR generated</div>
        <div className="empty-state-desc">
          Intermediate code is generated only after a successful compilation.
        </div>
      </div>
    );
  }

  return (
    <div className="fade-in">
      <div style={{ marginBottom: '0.5rem', fontSize: '0.78rem', color: 'var(--text-muted)' }}>
        {instructions.length} instructions generated
      </div>
      <div style={{
        background: 'var(--bg-base)',
        border: '1px solid var(--border)',
        borderRadius: '8px',
        padding: '0.75rem 1rem',
      }}>
        {instructions.map((instr) => (
          <div key={instr.index} className="ir-line">
            <span className="ir-idx">{String(instr.index).padStart(3, '0')}</span>
            <span className="ir-op" style={{ color: OP_COLOUR[instr.opcode] || 'var(--tok-keyword)' }}>
              {instr.opcode}
            </span>
            <span className="ir-args">
              {instr.arg1 && <span>{instr.arg1}</span>}
              {instr.arg2 && <span>{'  '}{instr.arg2}</span>}
              {instr.arg3 && <span className="ir-str">{'  '}"{instr.arg3}"</span>}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}
